(async () => {
  const workspace = (await figma.root.children).find(p => p.name.includes("03 · Workspace"));
  await figma.setCurrentPageAsync(workspace);

  // Helper to find node by name inside a parent
  function findNode(parent, name) {
    if (!parent) return null;
    if (parent.name === name) return parent;
    if (parent.children) {
      for (const child of parent.children) {
        const found = findNode(child, name);
        if (found) return found;
      }
    }
    return null;
  }

  const f1 = findNode(workspace, "01_Sign_In");
  const f2 = findNode(workspace, "02_Sign_Up");
  const f3 = findNode(workspace, "03_Home");
  const f4 = findNode(workspace, "04_Search");
  const f5 = findNode(workspace, "05_Explore_Products");
  const f6 = findNode(workspace, "06_Filter");
  const f7 = findNode(workspace, "07_Product_Overview");
  const f8 = findNode(workspace, "08_Product_Features");
  const f9 = findNode(workspace, "09_Shopping_Cart");
  const f10 = findNode(workspace, "10_Profile");

  function addReaction(triggerNode, targetFrame) {
    if (!triggerNode || !targetFrame) return;
    try {
      triggerNode.reactions = [
        {
          action: {
            type: "NODE",
            destinationId: targetFrame.id,
            navigation: "NAVIGATE",
            transition: null
          },
          trigger: { type: "ON_CLICK" }
        }
      ];
    } catch (e) {
      console.log("Error setting reaction:", e);
    }
  }

  // 1. 01_Sign_In links
  // Sign In → 03_Home
  // Sign Up here → 02_Sign_Up
  addReaction(findNode(f1, "Sign In"), f3);
  addReaction(findNode(f1, "Sign Up Link"), f2);

  // 2. 02_Sign_Up links
  // Sign Up → 03_Home
  // Sign In here → 01_Sign_In
  addReaction(findNode(f2, "Sign Up"), f3);
  addReaction(findNode(f2, "Sign In Link"), f1);

  // 3. 03_Home links
  // Search field → 04_Search
  // Shop now (first card) or See All → 05_Explore_Products
  // MOD-2 HD Wireless card → 07_Product_Overview
  // Avatar → 10_Profile
  addReaction(findNode(f3, "Search Field"), f4);
  addReaction(findNode(f3, "Shop Now 1"), f5);
  addReaction(findNode(f3, "See All Link"), f5);
  addReaction(findNode(f3, "MOD-2 HD Wireless Card"), f7);
  addReaction(findNode(f3, "Header Right Icon"), f10);

  // 4. 04_Search links
  // Back → 03_Home
  // Cart → 09_Shopping_Cart
  // Product row → 07_Product_Overview
  addReaction(findNode(f4, "Header Left Icon"), f3);
  addReaction(findNode(f4, "Header Right Icon"), f9);
  addReaction(findNode(f4, "Popular Product Row 1"), f7);

  // 5. 05_Explore_Products links
  // Back → 03_Home
  // Cart → 09_Shopping_Cart
  // Filter → 06_Filter
  // Product card → 07_Product_Overview
  addReaction(findNode(f5, "Header Left Icon"), f3);
  addReaction(findNode(f5, "Header Right Icon"), f9);
  addReaction(findNode(f5, "Filter Button"), f6);
  addReaction(findNode(f5, "Product Card 1"), f7);

  // 6. 06_Filter links
  // Apply Filter or close → 05_Explore_Products
  addReaction(findNode(f6, "Apply Filter Button"), f5);
  addReaction(findNode(f6, "Sheet Close Icon"), f5);

  // 7. 07_Product_Overview links
  // Back → 05_Explore_Products
  // Cart → 09_Shopping_Cart
  // Features tab → 08_Product_Features
  // Add To Cart → 09_Shopping_Cart
  addReaction(findNode(f7, "Header Left Icon"), f5);
  addReaction(findNode(f7, "Header Right Icon"), f9);
  addReaction(findNode(f7, "Features Tab"), f8);
  addReaction(findNode(f7, "Add To Cart Button"), f9);

  // 8. 08_Product_Features links
  // Back → 05_Explore_Products
  // Overview tab → 07_Product_Overview
  // Add To Cart → 09_Shopping_Cart
  addReaction(findNode(f8, "Header Left Icon"), f5);
  addReaction(findNode(f8, "Overview Tab"), f7);
  addReaction(findNode(f8, "Add To Cart Button"), f9);

  // 9. 09_Shopping_Cart links
  // Back → 07_Product_Overview
  addReaction(findNode(f9, "Header Left Icon"), f7);

  // 10. 10_Profile links
  // Back → 03_Home
  // Logout → 01_Sign_In
  addReaction(findNode(f10, "Header Left Icon"), f3);
  addReaction(findNode(f10, "Logout"), f1);

  console.log("All prototype connections wired successfully!");
})();
